+      decideValidationOutcome({
+        conclusion: "success",
+        ...agents,
+        latestAsk: { ...ask, at: "not-a-date" },
+        headCommittedAt: PUSHED,
+      }).next?.agent,
+    ).toBe("reviewer");
+  });
+
