+      conclusion: "success",
+      ...agents,
+      reviewerAgent: "engineer",
+      latestAsk: { agent: "engineer", author: { kind: "agent", agent: "reviewer" }, at: ASKED },
+      headCommittedAt: "2026-02-19T08:30:00Z",
+    });
+    expect(outcome.next?.agent).toBe("engineer");
+  });
+});
